custom_scss:
/* Base Styles (Always Centered) */
#page-login {
    background: url('http://slisdev.icfoss.org/files/slis_login_bg.png') no-repeat center center fixed;
    background-size: cover;
    height: 100vh;
    width: 100vw;

    /* THE FIX: Absolute centering using Flexbox */
    display: flex !important;
    justify-content: center !important; 
    align-items: center !important;
    margin: 0 !important;
}

.for-login {
    width: 400px;
    /* REMOVED: margin-right: 40vw (This was pushing it away from center) */
    margin: 0 !important; 
    z-index: 10;
}

.page-card {
    background-color: rgba(255, 255, 255, 0.9) !important;
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 10px 25px rgba(0,0,0,0.2);
    border: none !important;
}

/* --- LOGIN PAGE TITLE OVERRIDE --- */

.for-login .page-card-head h4 {
    display: none !important; /* Cleaner way to hide the old text */
}

.for-login .page-card-head::after {
    content: "Login to SLIS";
    font-size: 24px !important;
    font-weight: 700;
    display: block;
    color: #581908;
    text-align: center; /* Ensures text is centered in the card */
    padding: 10px 0;
}

/* Mobile Responsiveness */
@media (max-width: 768px) {
    .for-login {
        width: 90% !important;
        max-width: 350px;
    }

}

.page-card {
    background-color:  rgb(222 217 214) !important;
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 10px 25px rgba(0,0,0,.2);
    border: none !important;
}

