@import url("https://fonts.googleapis.com/css2?family=https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap:wght@300;400;500;600;700;800&display=swap");
// backward compatibility. deprecated in v15
$font-family-sans-serif: "https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap", "InterVariable", "Inter", -apple-system, BlinkMacSystemFont,
	"Segoe UI", "Roboto", "Oxygen", "Ubuntu", "Cantarell", "Fira Sans",
