:root {
	--font-stack: "https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap", "InterVariable", "Inter", -apple-system, BlinkMacSystemFont,
	"Segoe UI", "Roboto", "Oxygen", "Ubuntu", "Cantarell", "Fira Sans",
	"Droid Sans", "Helvetica Neue", sans-serif !important;
}
